let seed = 31;
const rand = (m) => { seed = (seed * 48271) % 2147483647; return seed % m; };
function need(w, c) { let d = 1, load = 0; for (const x of w) { if (load + x > c) { d++; load = 0; } load += x; } return d; }
function brute(w, days) { let c = Math.max(...w); while (need(w, c) > days) c++; return c; }
for (let k = 0; k < 40; k++) {
  const w = Array.from({ length: 1 + rand(10) }, () => 1 + rand(12));
  const d = 1 + rand(w.length);
  assertEqual(shipWithinDays(w, d), brute(w, d), JSON.stringify(w) + ' days=' + d);
}
